contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address _baseToken,
        address _nft,
        uint128 _virtualBaseTokenReserves,
        uint128 _virtualNftReserves,
        uint56 _changeFee,
        uint16 _feeRate,
        bytes32 _merkleRoot,
        bool _useStolenNftOracle,
        bool _payRoyalties
    ) public {
        require(_feeRate <= 5000, "fee rate too high");

        c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        );

        bool init = c.initialized();
        address baseToken = c.baseToken();
        address nft = c.nft();
        uint128 virtualBaseTokenReserves = c.virtualBaseTokenReserves();
        uint128 virtualNftReserves = c.virtualNftReserves();
        uint56 changeFee = c.changeFee();
        uint16 feeRate = c.feeRate();
        bytes32 merkleRoot = c.merkleRoot();
        bool useStolenNftOracle = c.useStolenNftOracle();
        bool payRoyalties = c.payRoyalties();

        bool reverted;
        try c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        ) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(
            init &&
            baseToken == _baseToken &&
            nft == _nft &&
            virtualBaseTokenReserves == _virtualBaseTokenReserves &&
            virtualNftReserves == _virtualNftReserves &&
            changeFee == _changeFee &&
            feeRate == _feeRate &&
            merkleRoot == _merkleRoot &&
            useStolenNftOracle == _useStolenNftOracle &&
            payRoyalties == _payRoyalties &&
            reverted
        );
    }
}

