contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(
        uint256[] memory inputTokenIds,
        uint256[] memory inputTokenWeights,
        bytes32[] memory inputProof,
        bool[] memory inputFlags,
        uint256[] memory outputTokenIds,
        uint256[] memory outputTokenWeights,
        bytes32[] memory outputProof,
        bool[] memory outputFlags,
        uint256 feeEther
    ) public payable {
        require(inputTokenIds.length == inputTokenWeights.length, "input length mismatch");
        require(outputTokenIds.length == outputTokenWeights.length, "output length mismatch");
        require(inputFlags.length + 1 == inputProof.length || inputFlags.length == 0, "bad input flags shape");
        require(outputFlags.length + 1 == outputProof.length || outputFlags.length == 0, "bad output flags shape");
        require(msg.value >= feeEther, "not enough ether sent");
        require(address(this).balance >= feeEther, "test contract balance too low");

        uint128 vBaseBefore = c.virtualBaseTokenReserves();
        uint128 vNftBefore = c.virtualNftReserves();

        C.MerkleMultiProof memory inputMulti;
        inputMulti.proof = inputProof;
        inputMulti.flags = inputFlags;

        C.MerkleMultiProof memory outputMulti;
        outputMulti.proof = outputProof;
        outputMulti.flags = outputFlags;

        IStolenNftOracle.Message[] memory emptyStolenProofs;

        bool reverted;
        try c.change{value: feeEther}(
            inputTokenIds,
            inputTokenWeights,
            inputMulti,
            emptyStolenProofs,
            outputTokenIds,
            outputTokenWeights,
            outputMulti
        ) returns (uint256 feeAmount, uint256 protocolFeeAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint128 vBaseAfter = c.virtualBaseTokenReserves();
        uint128 vNftAfter = c.virtualNftReserves();

        assert(
            reverted ||
            (vBaseAfter >= vBaseBefore &&
             vNftAfter <= vNftBefore &&
             uint256(vBaseAfter) - uint256(vBaseBefore) <= feeEther &&
             uint256(vNftBefore) - uint256(vNftAfter) <= inputTokenIds.length)
        );
    }
}

